expected_sql:
SELECT 
    (SUM(CASE WHEN ISSALESPERSON = TRUE THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN ISEMPLOYEE = TRUE THEN 1 ELSE 0 END)) AS SalesmenToEmployeesRatio
FROM APPLICATION.PEOPLE;

SELECT CUSTOMERNAME, ORDERCOUNT 
FROM REPORTS.MV_CUSTOMERORDERFREQUENCY
WHERE ORDERCOUNT > 130;

returned_sql:
SELECT STX.SUPPLIERTRANSACTIONID, STX.TRANSACTIONDATE, SP.SUPPLIERNAME
FROM PURCHASING.SUPPLIERTRANSACTIONS AS STX
JOIN WEBSITE.SUPPLIERS AS SP ON STX.SUPPLIERID = SP.SUPPLIERID;
